--
-- Name: generate_daily_sequence_id(text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.generate_daily_sequence_id(p_prefix text, p_width integer DEFAULT 4) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_key TEXT := p_prefix || to_char(now(), 'YYYYMMDD');
    v_no  INT;
BEGIN
    VALUES (v_key, 1)
    ON CONFLICT (id_key) DO UPDATE SET last_no = daily_id_counters.last_no + 1
    RETURNING last_no INTO v_no;

    RETURN v_key || '-' || lpad(v_no::text, p_width, '0');
END;
$$;


