--
-- Name: generate_lab_test_code(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.generate_lab_test_code(p_test_name text) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_prefix TEXT;
    v_period TEXT := to_char(now(), 'YYYYMM');
    v_no     INT;
BEGIN
    SELECT code_prefix INTO v_prefix FROM lab_test_catalog WHERE test_name = p_test_name;
    IF v_prefix IS NULL THEN
        RAISE EXCEPTION 'Unknown lab test: %', p_test_name;
    END IF;

    VALUES (v_prefix, v_period, 1)
    ON CONFLICT (code_prefix, period) DO UPDATE SET last_no = lab_test_code_counters.last_no + 1
    RETURNING last_no INTO v_no;

    RETURN v_prefix || '-' || v_period || '-' || lpad(v_no::text, 4, '0');
END;
$$;


ALTER FUNCTION public.generate_lab_test_code(p_test_name text) OWNER TO postgres;

--
-- Name: generate_next_census_no(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.generate_next_census_no(p_patient_type text) RETURNS text
    LANGUAGE plpgsql
    AS $_$
DECLARE
    v_period     TEXT := to_char(now(), 'YYYY-MM');
    v_actual_max INT;
    v_no         INT;
BEGIN
    SELECT COALESCE(MAX(substring(census_no FROM '\d+$')::int), 0)
      INTO v_actual_max
      FROM encounters
     WHERE patient_type = p_patient_type
       AND census_no IS NOT NULL;

    VALUES (p_patient_type, v_actual_max)
    ON CONFLICT (patient_type) DO UPDATE
        SET last_no = GREATEST(census_no_counters.last_no, v_actual_max);

    UPDATE census_no_counters
       SET last_no = last_no + 1
     WHERE patient_type = p_patient_type
    RETURNING last_no INTO v_no;

    RETURN v_period || '-' || v_no::text;
END;
$_$;


