--
-- Name: notify_new_lab_test(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.notify_new_lab_test() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    full_name      TEXT;
    test_form_type TEXT;
    roles          VARCHAR(30)[];
BEGIN
    SELECT form_type INTO test_form_type FROM lab_test_catalog WHERE test_name = NEW.test_name;

    SELECT trim(COALESCE(p.first_name, '') || ' ' || COALESCE(p.last_name, ''))
      INTO full_name
      FROM lab_orders o
      JOIN patients p ON p.id = o.patient_id
     WHERE o.id = NEW.order_id;

    roles := CASE
        WHEN test_form_type = 'Laboratory' THEN ARRAY['med_tech']
        ELSE ARRAY['xray_tech']
    END;

    VALUES (
        roles,
        'new_lab_test',
        'New Lab Order',
        COALESCE(full_name, 'A patient') || ' — ' || NEW.test_name || ' requested.',
        'lab_order',
        NEW.order_id
    );
    RETURN NEW;
END;
$$;


