--
-- Name: set_encounter_census_no(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_encounter_census_no() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.status = 'CANCELLED' THEN
        NEW.census_no := NULL;
    ELSIF (NEW.nurse_consultation_done = true OR NEW.doctor_consultation_done = true)
          AND NEW.census_no IS NULL THEN
        NEW.census_no := generate_next_census_no(COALESCE(NEW.patient_type, 'OPD Patient'));
    END IF;
    RETURN NEW;
END;
$$;


